def validate_grid(grid):
    if not grid:
        return False, "empty"
    rows = len(grid)
    cols = len(grid[0])
    for i, row in enumerate(grid):
        if len(row) != cols:
            return False, f"row {i} has {len(row)} cols, expected {cols}"
        for j, cell in enumerate(row):
            if not isinstance(cell, int):
                return False, f"cell ({i},{j}) is not int"
            if cell < 0 or cell > 9:
                return False, f"cell ({i},{j})={cell} out of range"
    return True, f"valid {rows}x{cols} grid"

